// Package calib holds bench calibration records and the per-backend speed
// factors fitted from them. Records live in calibration/data; the fitted
// factors are generated by scripts/fit-calibration into factors.json and
// embedded here. The package is pure: no I/O beyond the embedded file.
package calib

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"regexp"
	"sort"

	"github.com/shra26/ollama-compatibility-checker/internal/hw"
)

// Schema is the record format version.
const Schema = 1

// Record is one bench run shared by a user. It carries hardware model names
// and speeds only: no hostname, username, paths or serial numbers.
type Record struct {
	Schema          int     `json:"schema"`
	Date            string  `json:"date"` // YYYY-MM-DD
	ToolVersion     string  `json:"tool_version"`
	OllamaVersion   string  `json:"ollama_version"`
	OS              string  `json:"os"`
	Arch            string  `json:"arch"`
	CPU             string  `json:"cpu"`
	RAMBytes        uint64  `json:"ram_bytes"`
	RAMBandwidthGBs float64 `json:"ram_bandwidth_gbs"`
	UnifiedMemory   bool    `json:"unified_memory"`
	GPU             *GPU    `json:"gpu,omitempty"`
	Runs            []Run   `json:"runs"`
}

// GPU is the accelerator the runs used.
type GPU struct {
	Vendor                 string  `json:"vendor"`
	Name                   string  `json:"name"`
	Backend                string  `json:"backend"`
	VRAMBytes              uint64  `json:"vram_bytes"`
	BandwidthGBs           float64 `json:"bandwidth_gbs"`
	BandwidthLowConfidence bool    `json:"bandwidth_low_confidence"`
}

// Run is one model measured by bench.
type Run struct {
	Tag                 string  `json:"tag"`
	SizeBytes           uint64  `json:"size_bytes"`
	ActiveRatio         float64 `json:"active_ratio"` // active params / total params
	Ctx                 int     `json:"ctx"`
	EstTokS             float64 `json:"est_tok_s"`
	MeasuredTokS        float64 `json:"measured_tok_s"`
	PrefillTokS         float64 `json:"prefill_tok_s"`
	EstGPUFraction      float64 `json:"est_gpu_fraction"`
	MeasuredGPUFraction float64 `json:"measured_gpu_fraction"`
}

var dateRE = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)

// Validate checks a record before it is used for fitting.
func (r Record) Validate() error {
	switch {
	case r.Schema != Schema:
		return fmt.Errorf("schema %d, want %d", r.Schema, Schema)
	case !dateRE.MatchString(r.Date):
		return fmt.Errorf("date %q is not YYYY-MM-DD", r.Date)
	case r.RAMBytes == 0 || r.RAMBandwidthGBs <= 0:
		return errors.New("ram_bytes and ram_bandwidth_gbs must be > 0")
	case len(r.Runs) == 0:
		return errors.New("no runs")
	case r.GPU != nil && (r.GPU.Backend == "" || r.GPU.BandwidthGBs <= 0):
		return errors.New("gpu needs backend and bandwidth_gbs")
	}
	for _, u := range r.Runs {
		switch {
		case u.Tag == "" || u.SizeBytes == 0:
			return fmt.Errorf("run %q: tag and size_bytes required", u.Tag)
		case u.ActiveRatio <= 0 || u.ActiveRatio > 1:
			return fmt.Errorf("run %s: active_ratio %v outside (0, 1]", u.Tag, u.ActiveRatio)
		case u.MeasuredTokS <= 0:
			return fmt.Errorf("run %s: measured_tok_s must be > 0", u.Tag)
		}
	}
	return nil
}

// RefreshBandwidth replaces the GPU bandwidth recorded at bench time with the
// value from the current lookup tables, so a table fix (for example a GPU
// that was guessed) also corrects records shared before it.
func (r *Record) RefreshBandwidth() {
	if r.GPU == nil {
		return
	}
	if r.GPU.Backend == "metal" {
		if bw, ok := hw.LookupAppleBandwidth(r.GPU.Name); ok {
			r.GPU.BandwidthGBs, r.GPU.BandwidthLowConfidence = bw, false
		}
		return
	}
	r.GPU.BandwidthGBs, r.GPU.BandwidthLowConfidence = hw.LookupGPUBandwidth(r.GPU.Vendor, r.GPU.Name, r.GPU.VRAMBytes)
}

// Factor is the fitted decode efficiency for one backend.
type Factor struct {
	Eff      float64 `json:"eff"`     // median of measured efficiencies
	ErrPct   int     `json:"err_pct"` // expected error when using Eff, percent
	Runs     int     `json:"runs"`
	Machines int     `json:"machines"`
}

// Table maps a backend ("metal", "cuda", "rocm") to its Factor.
type Table map[string]Factor

// MinErrPct is the smallest error a fitted factor may claim. Bench runs on
// one machine vary by a few percent, and machines with the same chip differ.
const MinErrPct = 15

// FewMachinesErrPct is the floor while a backend has data from fewer than
// MinMachines machines: one machine's fit says little about other chips of
// the same backend (a laptop GPU versus a big desktop card, an M1 versus an
// M3 Max).
const (
	FewMachinesErrPct = 25
	MinMachines       = 3
)

// usable reports whether a run measures pure GPU decode efficiency: fully on
// GPU both estimated and measured, on a GPU with known bandwidth.
func usable(r Record, u Run) bool {
	return r.GPU != nil && !r.GPU.BandwidthLowConfidence &&
		u.EstGPUFraction == 1 && u.MeasuredGPUFraction >= 0.99
}

// efficiency is measured tok/s times bytes read per token over bandwidth.
func efficiency(bwGBs float64, u Run) float64 {
	return u.MeasuredTokS * float64(u.SizeBytes) * u.ActiveRatio / (bwGBs * 1e9)
}

// Fit computes one Factor per backend from fully-on-GPU runs. Call
// RefreshBandwidth on each record first. Eff is the
// median efficiency; ErrPct is the largest relative error that Eff makes on
// those runs, rounded up to 5 and at least MinErrPct, or FewMachinesErrPct
// while fewer than MinMachines machines contributed.
func Fit(rs []Record) Table {
	effs := map[string][]float64{}
	machines := map[string]map[string]bool{}
	for _, r := range rs {
		for _, u := range r.Runs {
			if !usable(r, u) {
				continue
			}
			b := r.GPU.Backend
			effs[b] = append(effs[b], efficiency(r.GPU.BandwidthGBs, u))
			if machines[b] == nil {
				machines[b] = map[string]bool{}
			}
			machines[b][fmt.Sprintf("%s|%d", r.GPU.Name, r.RAMBytes)] = true
		}
	}
	t := Table{}
	for b, v := range effs {
		m := median(v)
		worst := 0.0
		for _, e := range v {
			worst = math.Max(worst, math.Abs(e/m-1))
		}
		pct := int(math.Ceil(worst*100/5)) * 5
		floor := MinErrPct
		if len(machines[b]) < MinMachines {
			floor = FewMachinesErrPct
		}
		pct = max(pct, floor)
		t[b] = Factor{Eff: math.Round(m*1000) / 1000, ErrPct: pct, Runs: len(v), Machines: len(machines[b])}
	}
	return t
}

func median(v []float64) float64 {
	s := append([]float64(nil), v...)
	sort.Float64s(s)
	n := len(s)
	if n%2 == 1 {
		return s[n/2]
	}
	return (s[n/2-1] + s[n/2]) / 2
}

//go:embed factors.json
var factorsJSON []byte

// override replaces the embedded table in tests (see UseFactors).
var override Table

// UseFactors makes Factors return t until restore is called. Tests use it so
// their expected output does not change each time calibration data is added.
func UseFactors(t Table) (restore func()) {
	prev := override
	override = t
	return func() { override = prev }
}

// Factors returns the fitted table compiled into the binary, or the table set
// by UseFactors. It panics on malformed JSON, which
// TestEmbeddedFactorsUpToDate guards.
func Factors() Table {
	if override != nil {
		return override
	}
	var t Table
	if err := json.Unmarshal(factorsJSON, &t); err != nil {
		panic(err)
	}
	return t
}
